# -*- coding: utf-8 -*-
"""أدوات تسويق وتجارة إلكترونية مبتكرة (7): نماذج الإسناد، إرهاق الإعلانات، تقادم المخزون، أكواد الخصم، سلال الشراء، RFM، توزيع الميزانية بالعوائد المتناقصة."""
from biz_tools import F, S, add, CATS, T
PD = "const sum=a=>a.reduce((s,x)=>s+x,0);const pct=(a,b)=>b?a/b*100:0;const dt=s=>{s=String(s).replace(/[٠-٩]/g,d=>'٠١٢٣٤٥٦٧٨٩'.indexOf(d)).trim();let m;if(m=s.match(/^(\\d{1,2})[-\\/.](\\d{1,2})[-\\/.](\\d{4})$/))return new Date(+m[3],+m[2]-1,+m[1]);const d=new Date(s);return isNaN(d)?null:d};"

add('attribution-model-comparator', 'marketing', '🧭', 'مقارنة نماذج الإسناد التسويقي (آخر نقرة / أول نقرة / خطي / تناقصي / بالموضع)',
    'لا تحكم على قناة بنموذج واحد. أدخل مسارات العملاء قبل الشراء لترى كيف يتغير الفضل لكل قناة بين خمسة نماذج إسناد، وكيف تتغير ROAS، وأي القنوات تُظلم أو تُضخَّم في تقارير النقرة الأخيرة.',
    [F('d', 'المسارات (قنوات بالترتيب مفصولة بـ > | عدد التحويلات | قيمة التحويل)', 'textarea',
       'Meta > Google بحث > بريد | 40 | 260\nTikTok > Google بحث | 25 | 210\nGoogle بحث | 90 | 230\nMeta > بريد | 30 | 240\nInstagram > Meta > Google بحث | 18 | 300\nبريد | 45 | 200\nTikTok > Meta > Google بحث > بريد | 12 | 320', r=7),
     F('sp', 'الإنفاق لكل قناة (قناة | مبلغ) — اختياري', 'textarea', 'Meta | 22000\nGoogle بحث | 18000\nTikTok | 9000\nInstagram | 5000\nبريد | 1500', r=5),
     F('hl', 'عامل التناقص الزمني (وزن الخطوة الأسبق مقارنة بالأحدث)', 'n', 0.5)],
    r'''function compute(v){''' + PD + r'''
const J=lines(v.d).map(x=>({p:String(x[0]).split('>').map(s=>s.trim()).filter(Boolean),n:num(x[1]),v:num(x[2])})).filter(x=>x.p.length&&x.n>0);
if(!J.length)return'<b>أدخل مسارًا واحدًا على الأقل.</b>';
const M=['last','first','linear','decay','pos'],NM={last:'آخر نقرة',first:'أول نقرة',linear:'خطي',decay:'تناقصي زمنيًا',pos:'حسب الموضع 40/20/40'};
const ch={};const get=c=>ch[c]=ch[c]||{last:0,first:0,linear:0,decay:0,pos:0};
const hl=Math.min(1,Math.max(.1,v.hl||.5));
J.forEach(j=>{const val=j.n*j.v,P=j.p,n=P.length;
 get(P[n-1]).last+=val;get(P[0]).first+=val;
 P.forEach(c=>get(c).linear+=val/n);
 const w=P.map((c,i)=>Math.pow(hl,n-1-i)),tw=sum(w);P.forEach((c,i)=>get(c).decay+=val*w[i]/tw);
 if(n===1)get(P[0]).pos+=val;else if(n===2){get(P[0]).pos+=val*.5;get(P[1]).pos+=val*.5}else{get(P[0]).pos+=val*.4;get(P[n-1]).pos+=val*.4;P.slice(1,-1).forEach(c=>get(c).pos+=val*.2/(n-2))}});
const SP={};lines(v.sp).forEach(x=>{SP[x[0]]=num(x[1])});
const names=Object.keys(ch).sort((a,b)=>ch[b].linear-ch[a].linear),tot=sum(J.map(j=>j.n*j.v));
const rows=names.map(c=>[c].concat(M.map(m=>f(ch[c][m],0))).concat([f(Math.max(...M.map(m=>ch[c][m]))-Math.min(...M.map(m=>ch[c][m])),0)]));
const hasSp=Object.keys(SP).length>0;
const roas=hasSp?tbl(['القناة','الإنفاق'].concat(M.map(m=>'ROAS '+NM[m])),names.filter(c=>SP[c]>0).map(c=>[c,f(SP[c],0)].concat(M.map(m=>f(ch[c][m]/SP[c],2)+'x')))):'';
const sw=names.map(c=>({c:c,d:ch[c].last-ch[c].first,l:ch[c].linear})).sort((a,b)=>b.d-a.d);
const closer=sw[0],opener=sw[sw.length-1],rev=sum(J.map(j=>j.n));
const multi=pct(sum(J.filter(j=>j.p.length>1).map(j=>j.n)),rev);
return kpis([kpi('إجمالي الإيراد المُسنَد',f(tot,0)),kpi('عدد التحويلات',f(rev,0)),kpi('مسارات متعددة القنوات',f(multi,0)+'%'),kpi('أكثر قناة تُضخَّم بآخر نقرة',closer.c),kpi('أكثر قناة تُظلم',opener.c,'bad')])
+'<h4>الإيراد المُسنَد لكل قناة بحسب النموذج</h4>'+tbl(['القناة'].concat(M.map(m=>NM[m])).concat(['الفارق الأقصى']),rows)
+(hasSp?'<h4>ROAS حسب النموذج</h4>'+roas:'')
+rec(['«'+closer.c+'» تحصد فضلًا أكبر بنموذج آخر نقرة مما تستحق بنموذج الخطي؛ قد تكون قناة إغلاق لا قناة خلق طلب.','«'+opener.c+'» تفتح الرحلة لكنها تُظلم في آخر نقرة: لا توقفها اعتمادًا على ROAS آخر نقرة وحدها.','قارن القرارات: إن كانت القناة رابحة بكل النماذج فزد ميزانيتها بثقة، وإن كانت رابحة بنموذج واحد فاختبرها بتجربة إيقاف مؤقت.','للفضل الحقيقي استخدم اختبارات الرفع (Lift) أو تجارب جغرافية بجانب هذه النماذج.'])
+aiOut('أنت محلل تسويق. فسّر اختلاف نتائج نماذج الإسناد التالية واقترح إعادة توزيع الميزانية: '+JSON.stringify(names.map(c=>({c:c,last:Math.round(ch[c].last),first:Math.round(ch[c].first),linear:Math.round(ch[c].linear)}))))}''', True)

add('ad-creative-fatigue-detector', 'marketing', '😵', 'كاشف إرهاق الإعلانات ومتى تغيّر التصميم',
    'أدخل نسبة النقر الأسبوعية لكل إعلان مع التكرار وتكلفة التحويل ليكتشف أي الإعلانات بدأت تفقد فعاليتها، ويقدّر متى تصل لنقطة الخطر، ويقترح إيقاف أو تجديد أو توسيع.',
    [F('d', 'الإعلانات (إعلان | CTR% أسبوع1 | أسبوع2 | أسبوع3 | أسبوع4 | التكرار | CPA الحالي)', 'textarea',
       'فيديو خصم الجمعة | 2.4 | 2.2 | 1.7 | 1.2 | 4.1 | 62\nصورة المنتج الأساسي | 1.6 | 1.6 | 1.5 | 1.5 | 2.2 | 38\nكاروسيل المجموعة | 2.0 | 2.1 | 1.9 | 1.4 | 3.6 | 55\nشهادة عميل | 1.2 | 1.3 | 1.4 | 1.5 | 1.8 | 33', r=5),
     F('th', 'نسبة التراجع عن الذروة المسموحة %', 'n', 25), F('fq', 'حد التكرار', 'n', 3.5), F('cpa', 'CPA المستهدف', 'n', 45)],
    r'''function compute(v){''' + PD + r'''
const R=lines(v.d).map(x=>({n:x[0],c:[x[1],x[2],x[3],x[4]].map(num).filter(y=>y>0),fq:num(x[5]),cpa:num(x[6])})).filter(x=>x.n&&x.c.length>=3);
if(!R.length)return'<b>أدخل إعلانًا واحدًا على الأقل بثلاثة أسابيع بيانات.</b>';
R.forEach(x=>{const n=x.c.length,pk=Math.max(...x.c),last=x.c[n-1],drop=(pk-last)/pk*100;const xs=x.c.map((_,i)=>i),mx=sum(xs)/n,my=sum(x.c)/n;const sl=sum(xs.map((xi,i)=>(xi-mx)*(x.c[i]-my)))/Math.max(1e-9,sum(xs.map(xi=>(xi-mx)*(xi-mx))));x.drop=drop;x.sl=sl;x.last=last;x.pk=pk;const tgt=pk*(1-v.th/100);x.w=sl<0&&last>tgt?Math.ceil((last-tgt)/-sl):0;
 x.st=(drop>=v.th||x.fq>v.fq)&&x.cpa>v.cpa?'🔴 متعب — بدّل الآن':drop>=v.th*.6||x.fq>v.fq*.9?'🟠 بوادر إرهاق — جهّز بديلًا':sl>0&&x.cpa<=v.cpa?'🟢 صاعد — وسّع الميزانية':'🔵 مستقر'});
const bad=R.filter(x=>x.st.indexOf('🔴')===0),warn=R.filter(x=>x.st.indexOf('🟠')===0);
const rows=R.slice().sort((a,b)=>b.drop-a.drop).map(x=>[x.n,x.c.map(y=>f(y,1)).join(' ← '),f(x.drop,0)+'%',f(x.sl,2),f(x.fq,1),f(x.cpa,0),x.w?x.w+' أسبوع':'—',x.st]);
return kpis([kpi('إعلانات مفحوصة',R.length),kpi('متعبة',bad.length,bad.length?'bad':'good'),kpi('بوادر إرهاق',warn.length,warn.length?'bad':'good'),kpi('أعلى تراجع',f(Math.max(...R.map(x=>x.drop)),0)+'%'),kpi('متوسط التكرار',f(sum(R.map(x=>x.fq))/R.length,1))])
+'<h4>حالة كل إعلان</h4>'+tbl(['الإعلان','CTR الأسبوعي','تراجع عن الذروة','ميل الاتجاه','التكرار','CPA','أسابيع للخطر','الحالة'],rows)
+rec([bad.length?'استبدل فورًا: '+bad.map(x=>x.n).join('، ')+'. التكرار العالي مع تراجع النقر مؤشر كلاسيكي على إرهاق الجمهور.':'لا إعلانات متعبة حاليًا.','جهّز بدائل قبل بلوغ الخطر: غيّر أول 3 ثوانٍ من الفيديو أو العنوان أو الزاوية، لا اللون فقط.','وسّع الجمهور أو استبعد المتفاعلين عندما يرتفع التكرار فوق '+v.fq+'.','اختبر 3 إبداعات جديدة أسبوعيًا؛ معدل ذروة الإعلان الواحد عادة 2–4 أسابيع على الجمهور نفسه.'])}''')

add('inventory-aging-markdown-planner', 'ecom', '📦', 'مخطط تقادم المخزون وجدول التخفيضات المثلى',
    'ارفع مخزونك بأعماره ليحدد أي المنتجات تحتاج تخفيضًا الآن، وبأي نسبة، دون النزول تحت هامش الأمان، ويقدّر المبلغ المحرَّر من رأس المال وتكلفة الاحتفاظ التي توفرها.',
    [F('d', 'المخزون (منتج | وحدات | تكلفة الوحدة | السعر | عمر المخزون بالأيام | مبيعات شهرية)', 'textarea',
       'جاكيت شتوي | 220 | 90 | 220 | 160 | 18\nحقيبة سفر | 90 | 140 | 330 | 75 | 22\nقميص قطن | 600 | 25 | 75 | 40 | 150\nحذاء رياضي | 140 | 110 | 260 | 130 | 9\nعطر 100مل | 300 | 60 | 180 | 95 | 40', r=6),
     F('cc', 'تكلفة الاحتفاظ السنوية % (تخزين + تمويل + تقادم)', 'n', 24), F('fl', 'أدنى هامش على التكلفة %', 'n', 8), F('el', 'مرونة الطلب (زيادة المبيعات % لكل 1% خصم)', 'n', 1.8)],
    r'''function compute(v){''' + PD + r'''
const R=lines(v.d).map(x=>({n:x[0],u:num(x[1]),c:num(x[2]),p:num(x[3]),a:num(x[4]),s:num(x[5])})).filter(x=>x.n&&x.u>0&&x.p>0);
if(!R.length)return'<b>أدخل منتجًا واحدًا على الأقل.</b>';
R.forEach(x=>{x.cov=x.s>0?x.u/x.s:99;x.cap=x.u*x.c;x.cm=x.cap*(v.cc/100)/12;
 let d=0;if(x.a>=150||x.cov>=12)d=40;else if(x.a>=120||x.cov>=8)d=30;else if(x.a>=90||x.cov>=5)d=20;else if(x.a>=60||x.cov>=3.5)d=10;
 const floor=x.c*(1+v.fl/100),np0=x.p*(1-d/100);x.np=Math.max(np0,floor);x.d=(1-x.np/x.p)*100;x.capd=d>x.d+.5;
 const up=Math.min(300,v.el*x.d);x.ns=x.s*(1+up/100);x.nc=x.ns>0?x.u/x.ns:99;x.mg=(x.np-x.c)/x.np*100;x.rel=Math.min(x.u,x.ns*Math.min(x.nc,3))*x.np;
 x.sv=x.cm*(1-Math.min(1,x.nc/Math.max(.1,x.cov)))});
const act=R.filter(x=>x.d>0),T=sum(R.map(x=>x.cap)),slow=sum(R.filter(x=>x.cov>=5).map(x=>x.cap));
const rows=R.slice().sort((a,b)=>b.a-a.a).map(x=>[x.n,f(x.u,0),f(x.a,0),f(x.cov,1)+' شهر',f(x.cap,0),f(x.cm,0),x.d>0?'<b>'+f(x.d,0)+'%'+(x.capd?' (حد الأمان)':'')+'</b>':'لا تخفيض',x.d>0?f(x.np,0):f(x.p,0),x.d>0?f(x.mg,0)+'%':'—',x.d>0?f(x.nc,1)+' شهر':'—']);
return kpis([kpi('رأس مال المخزون',f(T,0)),kpi('بطيء (تغطية 5+ أشهر)',f(slow,0),slow?'bad':'good'),kpi('منتجات تحتاج تخفيضًا',act.length+' من '+R.length,act.length?'bad':'good'),kpi('تكلفة الاحتفاظ الشهرية',f(sum(R.map(x=>x.cm)),0)),kpi('وفر شهري متوقع',f(sum(R.map(x=>x.sv)),0),'good')])
+'<h4>خطة التخفيض لكل منتج</h4>'+tbl(['المنتج','وحدات','العمر (يوم)','تغطية المخزون','رأس المال','تكلفة احتفاظ/شهر','التخفيض','السعر الجديد','الهامش الجديد','تغطية بعد التخفيض'],rows)
+rec(['القاعدة: كلما طال العمر وارتفعت تغطية المخزون زاد التخفيض، وتدرّج بدل تخفيض كبير مرة واحدة (10% ثم 20% ثم 30%).',act.some(x=>x.capd)?'بعض الخصومات قُيّدت بحد الأمان '+v.fl+'% فوق التكلفة؛ للأصناف الأقدم فكّر في باقة أو تصفية بالجملة بدل النزول تحت التكلفة.':'كل الأسعار الجديدة فوق حد الأمان.','ما يُباع بتغطية أقل من 3 أشهر لا يحتاج خصمًا: لا تخفّض ما يتحرك.','أعد التقدير كل 30 يومًا واعتمد المبيعات الفعلية بعد التخفيض.','اجمع المنتجات الراكدة مع الأكثر مبيعًا في باقات لرفع التصريف دون خفض السعر المعلن.'])}''')

add('discount-code-roi-analyzer', 'ecom', '🎟️', 'محلل العائد الحقيقي لأكواد الخصم (الربح الإضافي لا الإيراد)',
    'كود الخصم قد يبدو ناجحًا بالإيراد وهو يخسر فعليًا لأن جزءًا من العملاء كانوا سيشترون بالسعر الكامل. يحسب الربح الإضافي الحقيقي لكل كود بعد المرتجعات والتآكل ويصنفها: كرّر، عدّل، أوقف.',
    [F('d', 'الأكواد (كود | استخدامات | إيراد بعد الخصم | إجمالي الخصم | عملاء جدد % | مرتجعات % | هامش المنتجات % قبل الخصم)', 'textarea',
       'WELCOME10 | 420 | 98000 | 10900 | 85 | 6 | 45\nFRIDAY30 | 1300 | 210000 | 90000 | 40 | 14 | 42\nVIP20 | 260 | 76000 | 19000 | 5 | 4 | 46\nINFLU15 | 540 | 88000 | 15500 | 70 | 9 | 40\nCART5 | 900 | 120000 | 6300 | 20 | 7 | 44', r=6),
     F('a', 'نسبة العملاء القدامى الذين كانوا سيشترون دون كود %', 'n', 60)],
    r'''function compute(v){''' + PD + r'''
const R=lines(v.d).map(x=>({n:x[0],u:num(x[1]),r:num(x[2]),ds:num(x[3]),nw:num(x[4])/100,rt:num(x[5])/100,m:num(x[6])/100})).filter(x=>x.n&&x.r>0);
if(!R.length)return'<b>أدخل كودًا واحدًا على الأقل.</b>';
const a=v.a/100;
R.forEach(x=>{const full=x.r+x.ds,old=1-x.nw;x.P=(full*x.m-x.ds)*(1-x.rt);x.cf=full*old*a*x.m*(1-x.rt);x.inc=x.P-x.cf;x.roi=x.ds?x.inc/x.ds*100:0;x.dp=pct(x.ds,full);x.aov=x.u?x.r/x.u:0;x.cpa=x.nw*x.u?x.ds/(x.nw*x.u):0;
 x.k=x.inc<0?'🔴 أوقف أو قيّد (يخسر)':x.roi<40?'🟠 عدّل: اخفض الخصم أو ضع حدًا أدنى للسلة':x.nw>=.5?'🟢 كرّر — يجلب عملاء جددًا':'🟢 كرّر'});
const S=R.slice().sort((a,b)=>b.inc-a.inc),T=sum(R.map(x=>x.inc)),D=sum(R.map(x=>x.ds));
const rows=S.map(x=>[x.n,f(x.u,0),f(x.r,0),f(x.dp,0)+'%',f(x.nw*100,0)+'%',f(x.rt*100,0)+'%',f(x.P,0),f(x.cf,0),'<b style="color:'+(x.inc>=0?'#0a7':'#c33')+'">'+f(x.inc,0)+'</b>',f(x.roi,0)+'%',f(x.cpa,0),x.k]);
const neg=R.filter(x=>x.inc<0);
return kpis([kpi('إجمالي الخصومات الممنوحة',f(D,0)),kpi('الربح الإضافي الحقيقي',f(T,0),T>=0?'good':'bad'),kpi('عائد الخصم الإجمالي',f(pct(T,D),0)+'%'),kpi('أكواد خاسرة',neg.length,neg.length?'bad':'good'),kpi('أفضل كود',S[0].n)])
+'<h4>الربح الإضافي لكل كود</h4>'+tbl(['الكود','استخدامات','إيراد','عمق الخصم','عملاء جدد','مرتجعات','ربح بالكود','ربح كان سيتحقق دونه','الربح الإضافي','عائد/خصم','تكلفة العميل الجديد','القرار'],rows)
+rec([neg.length?'الأكواد '+neg.map(x=>x.n).join('، ')+' تخسر رغم أنها تولّد إيرادًا: الخصم يُمنح لعملاء كانوا سيشترون أصلًا.':'كل الأكواد تحقق ربحًا إضافيًا.','الأكواد المخصصة للعملاء الجدد (مثل الترحيب) أعلى عائدًا عادة من الأكواد العامة.','حوّل الخصم العام إلى كوبون مشروط: حد أدنى للسلة أو لمنتجات محددة أو بمدة قصيرة.','قلّل نسبة التآكل بإخفاء الكود عن العملاء الحاليين أو منحه عند التخلي عن السلة فقط.'])}''')

add('basket-affinity-bundler', 'ecom', '🧺', 'محلل سلال الشراء واقتراح الباقات والبيع المتقاطع',
    'ألصق طلباتك (منتجات كل طلب مفصولة بفاصلة) فيكتشف أي المنتجات تُشترى معًا بدرجة تفوق المصادفة (Lift)، ويقترح باقات وعروض «يُشترى معه» مع نسب الثقة.',
    [F('d', 'الطلبات (كل سطر طلب: منتجات مفصولة بفاصلة)', 'textarea',
       'كفر جوال، شاحن، واقي شاشة\nكفر جوال، واقي شاشة\nسماعة، شاحن\nكفر جوال، شاحن\nحامل سيارة، شاحن سيارة\nسماعة، علبة سماعة\nكفر جوال، واقي شاشة، شاحن\nحامل سيارة، شاحن سيارة، كفر جوال\nسماعة، علبة سماعة، شاحن\nكفر جوال، واقي شاشة\nشاحن، كيبل\nكفر جوال، كيبل\nحامل سيارة، شاحن سيارة\nسماعة\nكفر جوال، واقي شاشة، كيبل', r=10),
     F('mn', 'أقل عدد طلبات مشتركة', 'n', 3), F('dc', 'خصم الباقة المقترح %', 'n', 10)],
    r'''function compute(v){''' + PD + r'''
const O=String(v.d).split('\n').map(l=>[...new Set(l.split(/[،,|]/).map(s=>s.trim()).filter(Boolean))]).filter(a=>a.length>0);
const N=O.length;if(N<5)return'<b>أدخل 5 طلبات على الأقل.</b>';
const c={},pr={};O.forEach(o=>{o.forEach(i=>c[i]=(c[i]||0)+1);for(let i=0;i<o.length;i++)for(let j=i+1;j<o.length;j++){const k=[o[i],o[j]].sort().join('||');pr[k]=(pr[k]||0)+1}});
const P=Object.keys(pr).map(k=>{const [a,b]=k.split('||'),n=pr[k];return{a:a,b:b,n:n,sup:n/N*100,ca:n/c[a]*100,cb:n/c[b]*100,lift:n*N/(c[a]*c[b])}}).filter(x=>x.n>=v.mn).sort((x,y)=>y.lift-x.lift||y.n-x.n);
const multi=O.filter(o=>o.length>1).length,top=Object.keys(c).sort((a,b)=>c[b]-c[a]).slice(0,5);
const rows=P.slice(0,12).map(x=>[x.a+' + '+x.b,x.n,f(x.sup,1)+'%',f(x.ca,0)+'% / '+f(x.cb,0)+'%','<b>'+f(x.lift,2)+'</b>',x.lift>=1.5?'🟢 باقة قوية':x.lift>=1?'🔵 بيع متقاطع':'⚪ ضعيفة']);
const sug=P.filter(x=>x.lift>=1).slice(0,5).map(x=>(x.ca>=x.cb?'عند شراء «'+x.a+'» اعرض «'+x.b+'» ('+f(x.ca,0)+'% يشترونهما معًا)':'عند شراء «'+x.b+'» اعرض «'+x.a+'» ('+f(x.cb,0)+'% يشترونهما معًا)'));
return kpis([kpi('عدد الطلبات',N),kpi('طلبات متعددة المنتجات',f(pct(multi,N),0)+'%'),kpi('أزواج مؤهلة',P.length,P.length?'good':'bad'),kpi('أقوى زوج',P[0]?P[0].a+' + '+P[0].b:'—'),kpi('أكثر منتج حضورًا',top[0])])
+'<h4>أزواج المنتجات المشتراة معًا</h4>'+(P.length?tbl(['الزوج','طلبات مشتركة','الدعم','الثقة (أ→ب / ب→أ)','Lift','التقييم'],rows):'<p>لا أزواج بعدد طلبات كافٍ؛ خفّض الحد الأدنى أو أضف طلبات.</p>')
+'<h4>أكثر المنتجات حضورًا في الطلبات</h4>'+tbl(['المنتج','الطلبات','حصته من الطلبات'],top.map(i=>[i,c[i],f(pct(c[i],N),0)+'%']))
+rec(P.length?['Lift أكبر من 1 يعني أن المنتجين يُشتريان معًا أكثر مما تتوقعه المصادفة؛ 1.5+ مرشح قوي لباقة.','اعرض الباقة بخصم '+v.dc+'% على الزوج الأقوى وراقب متوسط قيمة الطلب.'].concat(sug.map(s=>'نص عرض مقترح: '+s)):['زد عدد الطلبات أو خفّض الحد الأدنى لاستخراج علاقات موثوقة.'].concat(['كلما زادت الطلبات (يفضل 200+) صارت الأنماط أدق.']))
+note('الثقة أ→ب = من بين طلبات المنتج أ، كم نسبة ما يتضمن ب. الدعم = نسبة الطلبات الكلية التي تتضمن الزوج.')}''')

add('rfm-customer-segmentation', 'marketing', '🎯', 'تقسيم العملاء بنموذج RFM (الحداثة والتكرار والإنفاق) مع خطة تسويق لكل شريحة',
    'ألصق قائمة عملائك (آخر طلب وعدد الطلبات والإنفاق) ليقسّمهم تلقائيًا إلى أبطال ومخلصين وجدد وعملاء معرّضين للفقد وعملاء ضائعين، مع حجم كل شريحة وحصتها من الإيراد وإجراء تسويقي مقترح لكل شريحة.',
    [F('d', 'العملاء (عميل | تاريخ آخر طلب | عدد الطلبات | إجمالي الإنفاق)', 'textarea',
       'سارة | 2026-11-20 | 9 | 5400\nخالد | 2026-11-12 | 6 | 3100\nنورة | 2026-10-30 | 4 | 1700\nفهد | 2026-08-02 | 7 | 4200\nمها | 2026-11-24 | 1 | 220\nعبدالله | 2026-05-10 | 2 | 480\nريم | 2026-09-14 | 5 | 2300\nيوسف | 2026-11-02 | 3 | 900\nلمى | 2026-03-01 | 1 | 150\nماجد | 2026-10-18 | 8 | 4900\nهند | 2026-11-26 | 2 | 640\nتركي | 2026-07-05 | 3 | 1200', r=8),
     F('t', 'تاريخ اليوم', 'date', '2026-11-26')],
    r'''function compute(v){''' + PD + r'''
const today=dt(v.t)||new Date();
const R=lines(v.d).map(x=>({n:x[0],d:dt(x[1]),f:num(x[2]),m:num(x[3])})).filter(x=>x.n&&x.d&&x.f>0);
if(R.length<5)return'<b>أدخل 5 عملاء على الأقل.</b>';
R.forEach(x=>x.r=Math.max(0,Math.round((today-x.d)/864e5)));
const score=(arr,key,asc)=>{const s=arr.map(x=>x[key]).sort((a,b)=>asc?a-b:b-a);return x=>{const i=s.indexOf(x[key]),j=s.lastIndexOf(x[key]);return Math.max(1,Math.min(5,Math.ceil(((i+j)/2+1)/s.length*5)))}};
const sr=score(R,'r',false),sf=score(R,'f',true),sm=score(R,'m',true);
R.forEach(x=>{x.R=sr(x);x.F=sf(x);x.M=sm(x);
 x.s=x.R>=4&&x.F>=4&&x.M>=4?'🏆 أبطال':x.R<=2&&x.F>=4?'🚨 لا تخسره':x.R<=2&&x.F>=3?'⚠️ معرّض للفقد':x.F>=4&&x.R>=3?'💙 مخلص':x.R>=4&&x.F<=2?'🌱 جديد/واعد':x.R<=2?'💤 ضائع/خامل':'🔵 عادي'});
const ACT={'🏆 أبطال':'مكافآت حصرية وإطلاق مبكر للمنتجات وبرنامج إحالة؛ لا تعطهم خصومات عامة.','🚨 لا تخسره':'تواصل شخصي فوري، عرض مخصص كبير، واسأل عن سبب الغياب.','⚠️ معرّض للفقد':'حملة «اشتقنا لك» بعرض محدود المدة وتذكير بآخر منتجاتهم.','💙 مخلص':'ارفع قيمة السلة بباقات وبيع متقاطع واعرض عضوية أو نقاط.','🌱 جديد/واعد':'رسائل ترحيب وتعريف بالمنتجات والعودة للطلب الثاني خلال 30 يومًا.','💤 ضائع/خامل':'حملة استرجاع أخيرة بخصم قوي مرة واحدة ثم أوقف الإنفاق عليهم.','🔵 عادي':'محتوى قيمة وعروض موسمية، وراقب حركتهم.'};
const tot=sum(R.map(x=>x.m)),g={};R.forEach(x=>{const o=g[x.s]=g[x.s]||{n:0,m:0,r:0,f:0};o.n++;o.m+=x.m;o.r+=x.r;o.f+=x.f});
const rows=Object.keys(g).sort((a,b)=>g[b].m-g[a].m).map(k=>[k,g[k].n,f(pct(g[k].n,R.length),0)+'%',f(g[k].m,0),'<b>'+f(pct(g[k].m,tot),0)+'%</b>',f(g[k].m/g[k].n,0),f(g[k].r/g[k].n,0)+' يوم',f(g[k].f/g[k].n,1),ACT[k]]);
const risk=R.filter(x=>x.s==='🚨 لا تخسره'||x.s==='⚠️ معرّض للفقد');
const det=R.slice().sort((a,b)=>(b.R+b.F+b.M)-(a.R+a.F+a.M)).map(x=>[x.n,x.r+' يوم',x.f,f(x.m,0),x.R+'-'+x.F+'-'+x.M,x.s]);
return kpis([kpi('عدد العملاء',R.length),kpi('إجمالي الإنفاق',f(tot,0)),kpi('متوسط قيمة العميل',f(tot/R.length,0)),kpi('عملاء معرّضون للفقد',risk.length,risk.length?'bad':'good'),kpi('قيمة المعرّضين للفقد',f(sum(risk.map(x=>x.m)),0),risk.length?'bad':'good')])
+'<h4>الشرائح وخطة العمل</h4>'+tbl(['الشريحة','العملاء','النسبة','الإنفاق','حصة الإيراد','متوسط الإنفاق','متوسط الغياب','متوسط الطلبات','الإجراء المقترح'],rows)
+'<h4>العملاء بالتفصيل (R-F-M من 1 إلى 5)</h4>'+tbl(['العميل','منذ آخر طلب','الطلبات','الإنفاق','R-F-M','الشريحة'],det)
+rec(['ركّز الميزانية على الأبطال والمعرّضين للفقد؛ استرجاع عميل قديم أرخص بكثير من كسب جديد.',risk.length?'عملاء ذوو قيمة أوشكوا على المغادرة: '+risk.map(x=>x.n).join('، ')+'.':'لا عملاء عالي القيمة معرّضين للفقد حاليًا.','أعد التقسيم شهريًا؛ الدرجات نسبية بين عملائك وتتغير بتغير القاعدة.','اربط كل شريحة بتدفق آلي (بريد/واتساب) بدل الحملات اليدوية.'])}''')

add('marketing-budget-allocator', 'marketing', '⚖️', 'موزّع الميزانية التسويقية بنموذج العوائد المتناقصة',
    'الإنفاق المضاعف لا يضاعف المبيعات. يقدّر منحنى استجابة كل قناة من أدائها الحالي ودرجة إشباعها، ثم يوزّع الميزانية بحيث يتساوى العائد الحدّي بين القنوات، ويعرض الإيراد الإضافي مقارنة بتوزيعك الحالي.',
    [F('d', 'القنوات (قناة | ميزانية حالية | إيراد حالي | درجة الإشباع 0.2–0.9)', 'textarea',
       'Meta | 30000 | 120000 | 0.55\nGoogle بحث | 20000 | 110000 | 0.45\nTikTok | 10000 | 28000 | 0.7\nمؤثرون | 8000 | 20000 | 0.8\nبريد وواتساب | 2000 | 18000 | 0.35', r=6),
     F('tb', 'الميزانية الإجمالية الجديدة (0 = نفس الإجمالي الحالي)', 'n', 0), F('mn', 'أدنى حصة لكل قناة % (للحفاظ على التواجد)', 'n', 5)],
    r'''function compute(v){''' + PD + r'''
const C=lines(v.d).map(x=>({n:x[0],s:num(x[1]),r:num(x[2]),b:Math.min(.95,Math.max(.1,num(x[3])||.5))})).filter(x=>x.n&&x.s>0&&x.r>0);
if(C.length<2)return'<b>أدخل قناتين على الأقل.</b>';
const cur=sum(C.map(x=>x.s)),B=v.tb>0?v.tb:cur;
C.forEach(x=>{x.a=x.r/Math.pow(x.s,x.b);x.mr=(s)=>x.a*x.b*Math.pow(s,x.b-1);x.f=B*Math.max(0,v.mn||0)/100;x.o=x.f});
let left=B-sum(C.map(x=>x.o));const st=Math.max(B/2000,1);
if(left<0)return'<b>الحد الأدنى للحصص يتجاوز الميزانية.</b>';
while(left>st/2){let bi=0,bv=-1;C.forEach((x,i)=>{const m=x.mr(Math.max(x.o,1));if(m>bv){bv=m;bi=i}});C[bi].o+=Math.min(st,left);left-=Math.min(st,left)}
C.forEach(x=>{x.nr=x.a*Math.pow(x.o,x.b);x.cr=x.r;x.mc=x.mr(x.s);x.mo=x.mr(x.o)});
const cr=sum(C.map(x=>x.cr)),nr=sum(C.map(x=>x.nr)),gain=nr-cr;
const rows=C.map(x=>[x.n,f(x.s,0),f(x.o,0),(x.o>=x.s?'+':'')+f(x.o-x.s,0),f(x.cr,0),f(x.nr,0),f(x.r/x.s,2)+'x',f(x.nr/x.o,2)+'x',f(x.mc,2),f(x.mo,2),x.o>x.s*1.05?'⬆️ زد':x.o<x.s*.95?'⬇️ قلّل':'➡️ ثبّت']);
const best=C.slice().sort((a,b)=>b.mc-a.mc)[0],worst=C.slice().sort((a,b)=>a.mc-b.mc)[0];
return kpis([kpi('الميزانية الموزّعة',f(B,0)),kpi('الإيراد الحالي',f(cr,0)),kpi('الإيراد المتوقع بعد التوزيع',f(nr,0),'good'),kpi('الفرق',(gain>=0?'+':'')+f(gain,0),gain>=0?'good':'bad'),kpi('ROAS المختلط',f(nr/B,2)+'x')])
+'<h4>التوزيع الأمثل مقابل الحالي</h4>'+tbl(['القناة','ميزانية حالية','ميزانية مقترحة','التغيير','إيراد حالي','إيراد متوقع','ROAS حالي','ROAS متوقع','عائد حدّي حالي','عائد حدّي مقترح','القرار'],rows)
+rec(['العائد الحدّي هو الإيراد الإضافي لكل ريال إضافي: '+best.n+' أعلى قنواتك حدّيًا ('+f(best.mc,2)+') بينما '+worst.n+' الأدنى ('+f(worst.mc,2)+').','عند التوزيع الأمثل يتساوى العائد الحدّي تقريبًا بين القنوات، وأي نقل بعدها لا يزيد الإيراد.','النموذج تقديري (دالة قوة): انقل 20–30% من الفرق أولًا ثم قِس النتيجة قبل إكمال النقل.','لا تُلغِ قناة الاكتشاف تمامًا: ستقل عوائد القنوات الأخرى مع الوقت.'])
+aiOut('أنت استراتيجي تسويق. اقترح خطة تنفيذ تدريجية لإعادة توزيع الميزانية بين القنوات مع طريقة قياس: '+JSON.stringify(C.map(x=>({c:x.n,now:Math.round(x.s),proposed:Math.round(x.o)}))))}''', True)
